INSERT INTO clinlims.test_section(id,name,description,name_localization_id)
SELECT n,'AMR unit '||n,'AMR owned unit '||n,(SELECT min(id) FROM clinlims.localization)
FROM generate_series(990001,990002) n;
INSERT INTO clinlims.program(id,code,name,manually_changed,domain)
VALUES (990001,'AMR-BACTERIAL','AMR bacterial',false,'CLINICAL'),
       (990002,'AMR-TB','AMR TB',false,'CLINICAL'),
       (990003,'AMR-REVIEW','AMR chosen after review',false,'CLINICAL');
INSERT INTO clinlims.sample(id,accession_number,domain,entered_date,received_date)
SELECT n,'AMR-V01-'||n,'H',timestamp '2026-09-01 09:00:00',timestamp '2026-09-01 09:00:00'
FROM generate_series(990001,990003) n;
INSERT INTO clinlims.sample_item(id,sort_order,samp_id,typeosamp_id,status_id,collection_date)
SELECT n,1,n,(SELECT min(id) FROM clinlims.type_of_sample),(SELECT min(id) FROM clinlims.status_of_sample),
       timestamptz '2026-09-01 08:00:00+00'
FROM generate_series(990001,990003) n;
